"""Kitty data model: loading/saving kitty.json and all the money arithmetic.

All money is handled internally as whole cents (ints) so totals always add up
exactly. In kitty.json and in output, money is written as text with two
decimals, e.g. "41.40".
"""

import datetime
import json
import os
import re
import tempfile
from fractions import Fraction

FILENAME = "kitty.json"
FORMAT_VERSION = 1

_MONEY_RE = re.compile(r"^\d+(\.\d{1,2})?$")
_NUMBER_RE = re.compile(r"^(\d+(\.\d*)?|\.\d+)$")
_CURRENCY_RE = re.compile(r"^[A-Za-z]{3}$")
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


class KittyError(Exception):
    """A problem the user can fix; reported as a message, not a crash."""


# ---------------------------------------------------------------- parsing


def _cap(text):
    return text[:1].upper() + text[1:]


def parse_money(text, what="amount"):
    """Parse a positive amount like "45", "45.5" or "45.50" into cents."""
    text = text.strip()
    if not _MONEY_RE.match(text):
        raise KittyError(
            "{} must be a number with at most two decimals, like 45 or 45.50 "
            "(got {!r})".format(_cap(what), text)
        )
    whole, _, frac = text.partition(".")
    cents = int(whole) * 100 + int(frac.ljust(2, "0"))
    if cents <= 0:
        raise KittyError("{} must be more than zero (got {!r})".format(_cap(what), text))
    return cents


def parse_positive_number(text, what):
    """Parse a positive number (any number of decimals) into an exact Fraction."""
    text = text.strip()
    if not _NUMBER_RE.match(text):
        raise KittyError("{} must be a number (got {!r})".format(_cap(what), text))
    value = Fraction(text)
    if value <= 0:
        raise KittyError("{} must be more than zero (got {!r})".format(_cap(what), text))
    return value


def format_money(cents):
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return "{}{}.{:02d}".format(sign, cents // 100, cents % 100)


def format_number(value):
    """Write a Fraction that came from decimal text back as plain decimal text."""
    # Values only ever come from decimal input, so the denominator is 2^a*5^b.
    places = 0
    while (value * 10 ** places).denominator != 1:
        places += 1
    scaled = value * 10 ** places
    text = str(scaled.numerator).rjust(places + 1, "0")
    if places:
        text = text[:-places] + "." + text[-places:]
    return text


def parse_currency(text):
    text = text.strip()
    if not _CURRENCY_RE.match(text):
        raise KittyError(
            "Currency must be a three-letter code like EUR or USD (got {!r})".format(text)
        )
    return text.upper()


def parse_date(text):
    text = text.strip()
    try:
        if not _DATE_RE.match(text):
            raise ValueError
        return datetime.date.fromisoformat(text).isoformat()
    except ValueError:
        raise KittyError("Date must be a real date written YYYY-MM-DD, like 2026-07-14 (got {!r})".format(text))


def today():
    return datetime.date.today().isoformat()


def parse_name_list(text, what):
    names = [n.strip() for n in text.split(",")]
    if any(not n for n in names):
        raise KittyError("{} must be names separated by commas, like Alice,Bob (got {!r})".format(what, text))
    return names


def parse_name_values(text, what):
    """Parse "A=30,B=20" into a list of (name, value_text) pairs."""
    pairs = []
    for item in text.split(","):
        name, sep, value = item.partition("=")
        name, value = name.strip(), value.strip()
        if not sep or not name or not value:
            raise KittyError(
                "{} must look like Alice=30,Bob=20 (problem with {!r})".format(what, item.strip())
            )
        pairs.append((name, value))
    return pairs


def round_half_up(value):
    """Round a Fraction to the nearest whole number, halves away from zero."""
    if value >= 0:
        return int(value + Fraction(1, 2))
    return -int(-value + Fraction(1, 2))


def allocate(total, weights):
    """Split `total` cents in proportion to `weights` so the parts add up exactly.

    Each part is rounded down, then the leftover cents go to the parts that
    lost the most to rounding (earliest first on ties).
    """
    weight_sum = sum(weights)
    exact = [Fraction(total) * w / weight_sum for w in weights]
    parts = [int(x) for x in exact]
    leftover = total - sum(parts)
    order = sorted(range(len(weights)), key=lambda i: (-(exact[i] - parts[i]), i))
    for i in order[:leftover]:
        parts[i] += 1
    return parts


# ---------------------------------------------------------------- storage


def new_kitty(currency):
    return {
        "version": FORMAT_VERSION,
        "currency": currency,
        "members": [],
        "rates": {},
        "next_expense_id": 1,
        "next_payment_id": 1,
        "next_seq": 1,
        "expenses": [],
        "payments": [],
    }


def kitty_path(folder="."):
    return os.path.join(folder, FILENAME)


def load(folder="."):
    path = kitty_path(folder)
    if not os.path.exists(path):
        raise KittyError(
            "There's no kitty in this folder yet. Start one with: python3 -m kitty init EUR"
        )
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict) or "currency" not in data:
            raise ValueError
    except (OSError, ValueError):
        raise KittyError("Couldn't read {} - it may be damaged.".format(path))
    if data.get("version") != FORMAT_VERSION:
        raise KittyError("{} was made by a different version of kitty.".format(path))
    return data


def save(data, folder="."):
    """Write kitty.json safely: write a temporary file, then swap it in."""
    path = kitty_path(folder)
    fd, tmp = tempfile.mkstemp(dir=folder or ".", prefix=".kitty-", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
            f.write("\n")
        os.replace(tmp, path)
    except BaseException:
        if os.path.exists(tmp):
            os.remove(tmp)
        raise


# ---------------------------------------------------------------- members


def check_member(data, name):
    if name not in data["members"]:
        members = ", ".join(data["members"]) or "nobody yet"
        raise KittyError("{!r} isn't in the group (members: {})".format(name, members))


def add_member(data, name):
    name = name.strip()
    if not name:
        raise KittyError("Name can't be empty")
    if "," in name or "=" in name:
        raise KittyError("Names can't contain ',' or '=' (got {!r})".format(name))
    if name in data["members"]:
        raise KittyError("{!r} is already in the group".format(name))
    data["members"].append(name)
    return name


def remove_member(data, name):
    check_member(data, name)
    for e in data["expenses"]:
        if e["payer"] == name or name in e["shares"]:
            raise KittyError(
                "Can't remove {!r}: they're part of expense {} ({}). "
                "Remove those expenses first.".format(name, e["id"], e["description"])
            )
    for p in data["payments"]:
        if name in (p["from"], p["to"]):
            raise KittyError(
                "Can't remove {!r}: they're part of a payment on {}.".format(name, p["date"])
            )
    data["members"].remove(name)


# ---------------------------------------------------------------- rates


def set_rate(data, currency, rate_text):
    currency = parse_currency(currency)
    if currency == data["currency"]:
        raise KittyError("{} is the main currency; its rate is always 1".format(currency))
    rate = parse_positive_number(rate_text, "rate")
    data["rates"][currency] = format_number(rate)
    return currency, rate


def convert(data, cents, currency):
    """Return (rate_text, base_cents) for an amount in `currency`."""
    if currency == data["currency"]:
        return "1", cents
    if currency not in data["rates"]:
        raise KittyError(
            "No exchange rate for {cur} yet. Set one first, e.g.: "
            "python3 -m kitty rate set {cur} 0.92".format(cur=currency)
        )
    rate_text = data["rates"][currency]
    base = round_half_up(cents * Fraction(rate_text))
    if base <= 0:
        raise KittyError("That amount is worth less than one cent in {}".format(data["currency"]))
    return rate_text, base


# ---------------------------------------------------------------- expenses


def _check_unique(names, what):
    seen = set()
    for n in names:
        if n in seen:
            raise KittyError("{!r} appears twice in {}".format(n, what))
        seen.add(n)


def compute_split(data, amount, among=None, exact=None, shares=None, percent=None):
    """Work out who owes what, as a list of (name, weight) pairs.

    The weights are later used to split the main-currency amount, so the
    shares always add up exactly to it.
    """
    chosen = [opt for opt, v in (("--among", among), ("--exact", exact),
                                 ("--shares", shares), ("--percent", percent)) if v is not None]
    if len(chosen) > 1:
        raise KittyError("Use only one of {} at a time".format(", ".join(chosen)))

    if exact is not None:
        pairs = [(n, parse_money(v, "exact amount for " + n)) for n, v in parse_name_values(exact, "--exact")]
        total = sum(v for _, v in pairs)
        if total != amount:
            raise KittyError(
                "--exact amounts add up to {} but the expense is {}".format(
                    format_money(total), format_money(amount))
            )
    elif shares is not None:
        pairs = [(n, parse_positive_number(v, "share for " + n)) for n, v in parse_name_values(shares, "--shares")]
    elif percent is not None:
        pairs = [(n, parse_positive_number(v, "percent for " + n)) for n, v in parse_name_values(percent, "--percent")]
        total = sum(v for _, v in pairs)
        if total != 100:
            raise KittyError("--percent values add up to {} but must add up to 100".format(format_number(total)))
    else:
        if among is not None:
            names = parse_name_list(among, "--among")
        else:
            names = list(data["members"])
            if not names:
                raise KittyError("The group is empty. Add people first with: python3 -m kitty member add NAME")
        pairs = [(n, 1) for n in names]

    names = [n for n, _ in pairs]
    _check_unique(names, "the split")
    for n in names:
        check_member(data, n)
    # Keep shares in group order so listings are consistent.
    order = {m: i for i, m in enumerate(data["members"])}
    pairs.sort(key=lambda p: order[p[0]])
    return pairs


def add_expense(data, payer, amount_text, description, currency=None, date=None,
                category=None, among=None, exact=None, shares=None, percent=None):
    check_member(data, payer)
    amount = parse_money(amount_text)
    description = description.strip()
    if not description:
        raise KittyError("Description can't be empty")
    currency = parse_currency(currency) if currency is not None else data["currency"]
    date = parse_date(date) if date is not None else today()
    category = (category if category is not None else "other").strip()
    if not category:
        raise KittyError("Category can't be empty")

    pairs = compute_split(data, amount, among, exact, shares, percent)
    rate, base = convert(data, amount, currency)
    parts = allocate(base, [w for _, w in pairs])

    expense = {
        "id": data["next_expense_id"],
        "seq": data["next_seq"],
        "date": date,
        "payer": payer,
        "description": description,
        "amount": format_money(amount),
        "currency": currency,
        "rate": rate,
        "base_amount": format_money(base),
        "category": category,
        "shares": {n: format_money(c) for (n, _), c in zip(pairs, parts)},
    }
    data["next_expense_id"] += 1
    data["next_seq"] += 1
    data["expenses"].append(expense)
    return expense


def remove_expense(data, id_text):
    try:
        expense_id = int(id_text)
    except ValueError:
        raise KittyError("Expense ID must be a whole number (got {!r})".format(id_text))
    for i, e in enumerate(data["expenses"]):
        if e["id"] == expense_id:
            return data["expenses"].pop(i)
    raise KittyError("There's no expense with ID {}".format(expense_id))


def list_expenses(data):
    keys = ("id", "date", "payer", "description", "amount", "currency",
            "base_amount", "category", "shares")
    return [{k: e[k] for k in keys} for e in data["expenses"]]


# ---------------------------------------------------------------- payments


def add_payment(data, sender, receiver, amount_text, currency=None, date=None):
    check_member(data, sender)
    check_member(data, receiver)
    if sender == receiver:
        raise KittyError("Someone can't pay themselves back")
    amount = parse_money(amount_text)
    currency = parse_currency(currency) if currency is not None else data["currency"]
    date = parse_date(date) if date is not None else today()
    rate, base = convert(data, amount, currency)
    payment = {
        "id": data["next_payment_id"],
        "seq": data["next_seq"],
        "date": date,
        "from": sender,
        "to": receiver,
        "amount": format_money(amount),
        "currency": currency,
        "rate": rate,
        "base_amount": format_money(base),
    }
    data["next_payment_id"] += 1
    data["next_seq"] += 1
    data["payments"].append(payment)
    return payment


# ---------------------------------------------------------------- reports


def _cents(text):
    """Read money as stored in kitty.json ("41.40", "-20.70") back into cents."""
    sign = -1 if text.startswith("-") else 1
    whole, frac = text.lstrip("-").split(".")
    return sign * (int(whole) * 100 + int(frac))


def events_for(data, name):
    """Everything that changed `name`'s balance, oldest first: (date, seq, description, change)."""
    events = []
    for e in data["expenses"]:
        change = 0
        if e["payer"] == name:
            change += _cents(e["base_amount"])
        if name in e["shares"]:
            change -= _cents(e["shares"][name])
        if e["payer"] == name or name in e["shares"]:
            events.append((e["date"], e["seq"], e["description"], change))
    for p in data["payments"]:
        if p["from"] == name:
            events.append((p["date"], p["seq"], "Payment to " + p["to"], _cents(p["base_amount"])))
        elif p["to"] == name:
            events.append((p["date"], p["seq"], "Payment from " + p["from"], -_cents(p["base_amount"])))
    events.sort(key=lambda ev: (ev[0], ev[1]))
    return events


def balances(data):
    """Balance in cents per member: positive = owed money, negative = owes."""
    result = {m: 0 for m in data["members"]}
    for e in data["expenses"]:
        result[e["payer"]] += _cents(e["base_amount"])
        for n, share in e["shares"].items():
            result[n] -= _cents(share)
    for p in data["payments"]:
        base = _cents(p["base_amount"])
        result[p["from"]] += base
        result[p["to"]] -= base
    return result


def settle(data):
    """Suggest payments that bring everyone to zero.

    Repeatedly has the person who owes most pay the person who is owed most,
    which needs at most one payment fewer than the number of people.
    """
    order = {m: i for i, m in enumerate(data["members"])}
    owed = {m: b for m, b in balances(data).items() if b > 0}
    owing = {m: -b for m, b in balances(data).items() if b < 0}
    transfers = []
    while owed and owing:
        debtor = min(owing, key=lambda m: (-owing[m], order[m]))
        creditor = min(owed, key=lambda m: (-owed[m], order[m]))
        amount = min(owing[debtor], owed[creditor])
        transfers.append({"from": debtor, "to": creditor, "amount": format_money(amount)})
        owing[debtor] -= amount
        owed[creditor] -= amount
        if not owing[debtor]:
            del owing[debtor]
        if not owed[creditor]:
            del owed[creditor]
    return transfers


def history(data, name):
    check_member(data, name)
    running = 0
    rows = []
    for date, _, description, change in events_for(data, name):
        running += change
        rows.append({"date": date, "description": description,
                     "change": format_money(change), "balance": format_money(running)})
    return rows


def report(data):
    """Each member's share of spending per category (in the main currency)."""
    totals = {}
    for e in data["expenses"]:
        per_member = totals.setdefault(e["category"], {m: 0 for m in data["members"]})
        for n, share in e["shares"].items():
            per_member[n] += _cents(share)
    return {
        category: {m: format_money(c) for m, c in totals[category].items()}
        for category in sorted(totals)
    }


EXPORT_COLUMNS = ["id", "date", "payer", "description", "amount", "currency",
                  "category", "base_amount"]


def export_rows(data):
    return [[e[c] for c in EXPORT_COLUMNS] for e in data["expenses"]]
"""Command-line interface: `python3 -m kitty COMMAND ...`."""

import argparse
import csv
import json
import os
import sys

from kitty import core
from kitty.core import KittyError


class _Parser(argparse.ArgumentParser):
    """Argument parser that reports mistakes with exit status 1."""

    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(1, "Error: {}\n".format(message))


def build_parser():
    parser = _Parser(prog="python3 -m kitty",
                     description="Track shared trip costs and work out who owes whom.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND")
    commands.required = True

    p = commands.add_parser("init", help="start a new kitty")
    p.add_argument("currency", help="main currency, e.g. EUR")

    member = commands.add_parser("member", help="add, remove or list group members")
    member_cmds = member.add_subparsers(dest="action", metavar="ACTION")
    member_cmds.required = True
    member_cmds.add_parser("add", help="add someone").add_argument("name")
    member_cmds.add_parser("remove", help="remove someone").add_argument("name")
    member_cmds.add_parser("list", help="list everyone")

    expense = commands.add_parser("expense", help="add, remove or list expenses")
    expense_cmds = expense.add_subparsers(dest="action", metavar="ACTION")
    expense_cmds.required = True
    p = expense_cmds.add_parser("add", help="record that someone paid for something")
    p.add_argument("payer")
    p.add_argument("amount")
    p.add_argument("description", nargs="+")
    p.add_argument("--among", metavar="A,B", help="split equally between only these people")
    p.add_argument("--exact", metavar="A=30,B=20", help="split by exact amounts")
    p.add_argument("--shares", metavar="A=2,B=1", help="split by shares")
    p.add_argument("--percent", metavar="A=60,B=40", help="split by percentages")
    p.add_argument("--currency", help="currency it was paid in (default: main currency)")
    p.add_argument("--date", help="YYYY-MM-DD (default: today)")
    p.add_argument("--category", help='e.g. food (default: "other")')
    expense_cmds.add_parser("list", help="list all expenses")
    expense_cmds.add_parser("remove", help="delete an expense").add_argument("id")

    payment = commands.add_parser("payment", help="record someone paying someone back")
    payment_cmds = payment.add_subparsers(dest="action", metavar="ACTION")
    payment_cmds.required = True
    p = payment_cmds.add_parser("add", help="FROM paid AMOUNT to TO")
    p.add_argument("sender", metavar="FROM")
    p.add_argument("receiver", metavar="TO")
    p.add_argument("amount")
    p.add_argument("--currency", help="currency it was paid in (default: main currency)")
    p.add_argument("--date", help="YYYY-MM-DD (default: today)")

    rate = commands.add_parser("rate", help="set exchange rates")
    rate_cmds = rate.add_subparsers(dest="action", metavar="ACTION")
    rate_cmds.required = True
    p = rate_cmds.add_parser("set", help="one CURRENCY is worth RATE of the main currency")
    p.add_argument("currency")
    p.add_argument("rate")

    commands.add_parser("balances", help="how far up or down each person is")
    commands.add_parser("settle", help="suggest who should pay whom")
    commands.add_parser("history", help="everything that affected one person").add_argument("name")
    commands.add_parser("report", help="each person's share of spending per category")
    commands.add_parser("export", help="save expenses to a CSV file").add_argument("file")
    return parser


def print_json(value):
    print(json.dumps(value, ensure_ascii=False))


def run(args):
    if args.command == "init":
        currency = core.parse_currency(args.currency)
        if os.path.exists(core.kitty_path()):
            raise KittyError("There's already a kitty in this folder ({}). "
                             "Delete or move it first to start over.".format(core.FILENAME))
        core.save(core.new_kitty(currency))
        print("Started a new kitty in {}.".format(currency))
        return

    data = core.load()
    cmd = (args.command, getattr(args, "action", None))

    if cmd == ("member", "add"):
        name = core.add_member(data, args.name)
        core.save(data)
        print("Added {}.".format(name))
    elif cmd == ("member", "remove"):
        core.remove_member(data, args.name)
        core.save(data)
        print("Removed {}.".format(args.name))
    elif cmd == ("member", "list"):
        print_json(data["members"])
    elif cmd == ("expense", "add"):
        expense = core.add_expense(
            data, args.payer, args.amount, " ".join(args.description),
            currency=args.currency, date=args.date, category=args.category,
            among=args.among, exact=args.exact, shares=args.shares, percent=args.percent)
        core.save(data)
        print(expense["id"])
    elif cmd == ("expense", "list"):
        print_json(core.list_expenses(data))
    elif cmd == ("expense", "remove"):
        expense = core.remove_expense(data, args.id)
        core.save(data)
        print("Removed expense {} ({}).".format(expense["id"], expense["description"]))
    elif cmd == ("payment", "add"):
        payment = core.add_payment(data, args.sender, args.receiver, args.amount,
                                   currency=args.currency, date=args.date)
        core.save(data)
        print("Recorded {} paying {} {} {}.".format(
            payment["from"], payment["to"], payment["amount"], payment["currency"]))
    elif cmd == ("rate", "set"):
        currency, _ = core.set_rate(data, args.currency, args.rate)
        core.save(data)
        print("1 {} = {} {}.".format(currency, data["rates"][currency], data["currency"]))
    elif args.command == "balances":
        print_json({m: core.format_money(c) for m, c in core.balances(data).items()})
    elif args.command == "settle":
        print_json(core.settle(data))
    elif args.command == "history":
        print_json(core.history(data, args.name))
    elif args.command == "report":
        print_json(core.report(data))
    elif args.command == "export":
        export(data, args.file)


def export(data, filename):
    target = os.path.abspath(filename)
    if os.path.basename(target) == core.FILENAME or target == os.path.abspath(core.kitty_path()):
        raise KittyError("Refusing to overwrite {} - pick another file name.".format(core.FILENAME))
    with open(target, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(core.EXPORT_COLUMNS)
        writer.writerows(core.export_rows(data))
    print("Saved {} expense(s) to {}.".format(len(data["expenses"]), filename))


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        run(args)
    except KittyError as e:
        print("Error: {}".format(e), file=sys.stderr)
        return 1
    except OSError as e:
        print("Error: couldn't access {}: {}".format(e.filename or "a file", e.strerror or e),
              file=sys.stderr)
        return 1
    return 0
import sys

from kitty.cli import main

sys.exit(main())
